shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/src/acl.c
+++ b/src/acl.c
@@ -2377,6 +2377,8 @@
         listRewind(server.clients, &li);
         while ((ln = listNext(&li)) != NULL) {
             client *c = listNodeValue(ln);
+            /* Skip clients not subject to ACL rules, such as the primary. */
+            if (!c->user) continue;
             user *original = c->user;
             list *channels = NULL;
             user *new_user = ACLGetUserByName(c->user->name, sdslen(c->user->name));
PATCH
make -j4 > /tmp/valkey-acl-build.log 2>&1; result=$?; tail -30 /tmp/valkey-acl-build.log; exit "$result"

